UPDATE tianquan_oauth.oauth_identity_tenant
SET tenant_name = #{po.tenantName},
    status = #{po.status},
    settings = #{po.settings, typeHandler=top.egon.cola.platform.tianquan.shoubing.admin.tenant.dao.IdentityTenantSettingsJsonbTypeHandler},
    version = #{po.version},
    update_user_id = #{po.updateUserId},
    update_time = #{po.updateTime}
WHERE tenant_id = #{directoryPartitionId}
  AND id = #{po.id}
  AND identity_tenant_id = #{po.identityTenantId}
  AND version = #{expectedVersion}
  AND deleted_at IS NULL
